import{_ as i,C as n,o as a,c as s,a2 as o,b as c,w as r,a as d,E as l,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const y=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-XI/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-XI/Lectura_Catedra_Evaluacion_3.md"}'),m={name:"materias/Proyecto_Sociotecnologico_IV/documentacion/IV-XI/Lectura_Catedra_Evaluacion_3.md"};function g(p,e,f,A,b,h){const t=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-xi" tabindex="-1">Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre XI) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iv-trayecto-iv-trimestre-xi" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico IV (Trayecto IV - Trimestre XI)&quot;">​</a></h2><h3 id="eje-tematico-seguridad-criptografica-diseno-de-datos-e-integracion-hardware-software" tabindex="-1">Eje Temático: Seguridad Criptográfica, Diseño de Datos e Integración Hardware/Software <a class="header-anchor" href="#eje-tematico-seguridad-criptografica-diseno-de-datos-e-integracion-hardware-software" aria-label="Permalink to &quot;Eje Temático: Seguridad Criptográfica, Diseño de Datos e Integración Hardware/Software&quot;">​</a></h3><hr><h2 id="🧭-introduccion-seguridad-integral-y-convergencia-tecnologica" tabindex="-1">🧭 Introducción: Seguridad Integral y Convergencia Tecnológica <a class="header-anchor" href="#🧭-introduccion-seguridad-integral-y-convergencia-tecnologica" aria-label="Permalink to &quot;🧭 Introducción: Seguridad Integral y Convergencia Tecnológica&quot;">​</a></h2><p>En el ejercicio profesional de la ingeniería en informática, la seguridad no es un módulo optativo; es un <strong>requerimiento no funcional crítico de carácter no negociable</strong>.</p><p>Los proyectos de PST IV a menudo manejan datos médicos confidenciales, censos poblacionales protegidos por la Ley de Protección de Datos o información crítica de infraestructura pública. Asimismo, muchos proyectos integran software con <strong>dispositivos de hardware</strong> (sensores de ambiente, lectores biométricos, microcontroladores o sistemas de telemetría). Este manual detalla los protocolos criptográficos y las arquitecturas de integración física y lógica exigidas.</p><hr><h2 id="🔒-capitulo-i-seguridad-criptografica-y-autenticacion-industrial" tabindex="-1">🔒 CAPÍTULO I: Seguridad Criptográfica y Autenticación Industrial <a class="header-anchor" href="#🔒-capitulo-i-seguridad-criptografica-y-autenticacion-industrial" aria-label="Permalink to &quot;🔒 CAPÍTULO I: Seguridad Criptográfica y Autenticación Industrial&quot;">​</a></h2>',9)),(a(),c(u,null,{default:r(()=>[l(t,{id:"mermaid-23",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20User%5B%22%F0%9F%91%A4%20Cliente%20%2F%20Dispositivo%22%5D%20--%3E%7CCredenciales%7C%20Auth%5B%22%F0%9F%94%90%20Servidor%20de%20Autenticaci%C3%B3n%22%5D%0A%20%20%20%20Auth%20--%3E%7CGenera%20Token%20Firmado%20Asim%C3%A9tricamente%7C%20Token%5B%22%F0%9F%8E%AB%20JWT%20(JSON%20Web%20Token)%3Cbr%3EFirmado%20con%20Clave%20Privada%20(RSA%20%2F%20Ed25519)%22%5D%0A%20%20%20%20Token%20--%3E%20User%0A%20%20%20%20User%20--%3E%7CPetici%C3%B3n%20con%20Bearer%20Token%7C%20API%5B%22%E2%9A%99%EF%B8%8F%20API%20Gateway%20%2F%20Backend%22%5D%0A%20%20%20%20API%20--%3E%7CValida%20con%20Clave%20P%C3%BAblica%7C%20Data%5B%22%F0%9F%97%84%EF%B8%8F%20Acceso%20a%20Datos%20Seguros%22%5D%0A%0A%20%20%20%20style%20User%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20Auth%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20Token%20fill%3A%23b45309%2Cstroke%3A%23f59e0b%2Ccolor%3A%23fff%0A%20%20%20%20style%20API%20fill%3A%231e3a8a%2Cstroke%3A%233b82f6%2Ccolor%3A%23fff%0A%20%20%20%20style%20Data%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="_1-1-control-de-acceso-basado-en-atributos-abac-vs-roles-rbac" tabindex="-1">1.1 Control de Acceso Basado en Atributos (ABAC) vs. Roles (RBAC) <a class="header-anchor" href="#_1-1-control-de-acceso-basado-en-atributos-abac-vs-roles-rbac" aria-label="Permalink to &quot;1.1 Control de Acceso Basado en Atributos (ABAC) vs. Roles (RBAC)&quot;">​</a></h3><p>En sistemas de ingeniería complejos, no basta con roles fijos (<code>Admin</code>, <code>Operador</code>). Se implementa <strong>ABAC (Attribute-Based Access Control)</strong>:</p><ul><li>El acceso se evalúa dinámicamente según: <ul><li><em>Sujeto:</em> Rol y departamento del usuario.</li><li><em>Acción:</em> Leer, Escribir, Anular, Aprobar.</li><li><em>Recurso:</em> Tipo de expediente o monto de la transacción.</li><li><em>Contexto Ambiental:</em> Horario laboral permitido (ej: no permitir transferencias a las 3:00 AM) y subred IP de procedencia.</li></ul></li></ul><h3 id="_1-2-cifrado-de-datos-en-reposo-y-en-transito" tabindex="-1">1.2 Cifrado de Datos en Reposo y en Tránsito <a class="header-anchor" href="#_1-2-cifrado-de-datos-en-reposo-y-en-transito" aria-label="Permalink to &quot;1.2 Cifrado de Datos en Reposo y en Tránsito&quot;">​</a></h3><ul><li><strong>En Tránsito:</strong> Forzar protocolo <strong>TLS 1.3</strong> con suites de cifrado seguras y certificados digitales válidos.</li><li><strong>En Reposo:</strong> Los campos sensibles en la base de datos (datos clínicos, números de cuentas bancarias) se cifran mediante algoritmos autenticados como <strong>AES-256-GCM</strong> antes de ser insertados en el SGBD.</li></ul><hr><h2 id="🔌-capitulo-ii-integracion-hardware-software-y-protocolos-de-comunicacion" tabindex="-1">🔌 CAPÍTULO II: Integración Hardware/Software y Protocolos de Comunicación <a class="header-anchor" href="#🔌-capitulo-ii-integracion-hardware-software-y-protocolos-de-comunicacion" aria-label="Permalink to &quot;🔌 CAPÍTULO II: Integración Hardware/Software y Protocolos de Comunicación&quot;">​</a></h2><p>Cuando el sistema interactúa con hardware externo (sensores, torniquetes, microcontroladores ESP32/Raspberry Pi):</p><table tabindex="0"><thead><tr><th>Protocolo</th><th>Naturaleza</th><th>Ámbito de Uso en PST IV</th></tr></thead><tbody><tr><td><strong>MQTT (Message Queuing Telemetry Transport)</strong></td><td>Publicación / Suscripción ligero</td><td>Envío continuo de telemetría desde sensores (temperatura, nivel de agua, consumo eléctrico) hacia el backend sin sobrecargar la red.</td></tr><tr><td><strong>WebSockets (WSS)</strong></td><td>Comunicación bidireccional en tiempo real</td><td>Monitoreo en vivo en el panel web de control sin necesidad de refrescar la página.</td></tr><tr><td><strong>Serial / USB (UART)</strong></td><td>Comunicación cableada directa</td><td>Conexión con básculas industriales, lectores de código de barras o módems GSM/GPRS.</td></tr><tr><td><strong>REST APIs (HTTP/JSON)</strong></td><td>Peticiones cliente-servidor síncronas</td><td>Registro de transacciones formales y consultas bajo demanda.</td></tr></tbody></table><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-3" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 3 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-3" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 3&quot;">​</a></h2><p>Para la Evaluación 3 del Trimestre XI:</p><ol><li><strong>Dossier de Seguridad y Criptografía:</strong> Especificación de protocolos de autenticación (JWT/OAuth), gestión de secretos y políticas de cifrado.</li><li><strong>Modelo de Datos Físico Optimizado:</strong> Con scripts DDL, índices avanzados y disparadores de auditoría.</li><li><strong>Diagrama de Integración Hardware/Software:</strong> Con especificación de protocolos, puertos y tramas de comunicación (si el proyecto incluye hardware).</li></ol>',13))])}const _=i(m,[["render",g]]);export{y as __pageData,_ as default};
